  const vee=R()<0.5, f=vee?(x=>Math.abs(x)):(x=>x*x/2), g=x=>f(x-h)+k, s=v=>v<0?' + '+(-v):' − '+v, p=v=>v<0?' − '+(-v):' + '+v;
