    if((Math.random()<0.5)!==v) continue; const F=['∀x ∃y R(x, y)','∃y ∀x R(x, y)','∀x R(x, x)','∃x R(x, x)','∀x ∀y (R(x, y) ⇒ R(y, x))'][k], opts=['true in this world','false in this world'];
