/* ================= E. counts: sums by induction and the choosing table (4c, 4k) ================= */
const SUMS={odds:['the odd numbers 1 + 3 + ⋯ + (2n + 1)',n=>(n+1)*(n+1),n=>2*n+1],squares:['the squares 0² + 1² + ⋯ + n²',n=>n*(n+1)*(2*n+1)/6,n=>n*n],
  cubes:['the cubes 0³ + 1³ + ⋯ + n³',n=>Math.pow(n*(n+1)/2,2),n=>n*n*n],oddsq:['the odd squares 1² + 3² + ⋯ + (2n + 1)²',n=>(n+1)*(2*n+1)*(2*n+3)/3,n=>(2*n+1)*(2*n+1)]};
SEEDS.push({id:'4k.bkrows',step:'4k',kind:'num',label:'row numbers of the choosing table',make(){ const n=ri(3,9); return {val:num(n),ix:String(n)}; }});
NL({id:'4k.sumto',steps:()=>['4c','4k'],make:()=>({s:pick1(Object.keys(SUMS))}),say:p=>'add up '+SUMS[p.s][0]+', n the number',act:(s,p)=>{ const n=iv(s); if(n===null||n<1||n>12) return null; const v=SUMS[p.s][1](n); return v<=99999?num(v):null; },
  cite:()=>'proof by induction',slips:(s,p)=>{ const n=iv(s); if(n===null||n<1) return []; return [{why:'the sum stops one term early',v:Q(SUMS[p.s][1](n-1))},{why:'the last term is counted twice',v:Q(SUMS[p.s][1](n)+SUMS[p.s][2](n))}]; },
  line:(o,p,nm,nx,s)=>'with n = '+qs(s.v)+', '+SUMS[p.s][0].replace(/ \+ ⋯ \+ .*$/,' + ⋯')+' up to '+SUMS[p.s][2](iv(s))+': '+qs(o.v)});
NL({id:'4k.rowstep',steps:()=>['4k'],make:cur=>{ const n=iv(cur); return n!==null&&n>=2&&n<=12?{j:ri(1,n)}:null; },say:p=>'find entry '+p.j+' of the row after row n of the choosing table, n the number',
  act:(s,p)=>{ const n=iv(s); return n===null||n<p.j||n>12?null:num(C2(n+1,p.j)); },cite:()=>'the row-step technique',
  slips:(s,p)=>{ const n=iv(s); if(n===null) return []; return [{why:'entries '+p.j+' and '+(p.j+1)+' of the row above are added, not '+(p.j-1)+' and '+p.j,v:Q(C2(n,p.j)+C2(n,p.j+1))},{why:'only the entry above is taken',v:Q(C2(n,p.j))}]; },
  line:(o,p,nm,nx,s)=>'entry '+p.j+' of row '+(iv(s)+1)+': '+C2(iv(s),p.j-1)+' + '+C2(iv(s),p.j)+' = '+qs(o.v)});
NL({id:'4k.twoterm',steps:()=>['4k'],make:cur=>{ const n=iv(cur); return n!==null&&n>=2&&n<=10?{j:ri(1,n-1),v:pick1([['a','b'],['x','y'],['p','q']])}:null; },
  say:p=>'spread out ('+p.v[0]+' + '+p.v[1]+')ⁿ, n the number: how many times does '+p.v[1]+sup(p.j)+' come up?',
  act:(s,p)=>{ const n=iv(s); return n===null||n<=p.j||n>10?null:num(C2(n,p.j)); },cite:()=>'the two-term-power technique',
  slips:(s,p)=>{ const n=iv(s); if(n===null) return []; return [{why:'the entry is counted from 1 instead of 0',v:Q(C2(n,p.j-1))},{why:'row '+(n-1)+' of the table is read instead of row '+n,v:Q(C2(n-1,p.j))}]; },
  line:(o,p,nm,nx,s)=>'the term '+p.v[0]+sup(iv(s)-p.j).replace(/^¹$/,'')+p.v[1]+sup(p.j).replace(/^¹$/,'')+' in ('+p.v[0]+' + '+p.v[1]+')'+sup(iv(s))+': '+qs(o.v)+' times'});

/* ================= F. sets of reals: domains (9f), sign charts (8g), bars (8h) ================= */
/* a set of reals, sampled at its break points (all fractions) and between them */
function realSet(crit,test){ const pts=uniqQ(crit); const reg=[]; if(!pts.length){ return {pts,reg:[test(Q(0))]}; }
  reg.push(test(qsub(pts[0],Q(1)))); pts.forEach((p,i)=>{ reg.push(test(p)); reg.push(test(i+1<pts.length?mid(p,pts[i+1]):qa(p,Q(1)))); }); return {pts,reg}; }
function setPieces(S){ const {pts,reg}=S, n=pts.length; if(!n) return reg[0]?[{lo:null,hi:null}]:[]; const out=[]; let cur=null;
  for(let i=0;i<reg.length;i++){ const isPt=i%2===1, k=(i-1)>>1, inn=reg[i];
    if(inn){ if(!cur){ cur=isPt?{lo:pts[k],loIn:true}:{lo:i===0?null:pts[(i-2)>>1],loIn:false}; } if(isPt){ cur.hi=pts[k]; cur.hiIn=true; } else { cur.hi=i===reg.length-1?null:pts[i>>1]; cur.hiIn=false; } }
    else if(cur){ out.push(cur); cur=null; } }
  if(cur) out.push(cur); return out; }
function setText(S,style){ const pc=setPieces(S); if(!pc.length) return style==='iv'?'no real x':'no real x';
  if(pc.length===1&&pc[0].lo===null&&pc[0].hi===null) return 'every real x';
  const holes=S.pts.filter((p,i)=>!S.reg[2*i+1]&&S.reg[2*i]&&S.reg[2*i+2]); if(holes.length===S.pts.length&&S.reg.every((r,i)=>i%2===1||r)&&holes.length<=3&&style!=='iv') return 'every real x but '+holes.map(qs).join(' and ');
  if(style==='iv') return pc.map(c=>c.lo!==null&&c.hi!==null&&qe(c.lo,c.hi)?'{'+qs(c.lo)+'}':(c.lo===null?'(−∞':(c.loIn?'[':'(')+qs(c.lo))+', '+(c.hi===null?'∞)':qs(c.hi)+(c.hiIn?']':')'))).join(' ∪ ');
  return pc.map(c=>c.lo!==null&&c.hi!==null&&qe(c.lo,c.hi)?'x = '+qs(c.lo):c.lo===null?'x '+(c.hiIn?'≤':'<')+' '+qs(c.hi):c.hi===null?(pc.length>1?qs(c.lo)+' '+(c.loIn?'≤':'<')+' x':'x '+(c.loIn?'≥':'>')+' '+qs(c.lo)):qs(c.lo)+' '+(c.loIn?'≤':'<')+' x '+(c.hiIn?'≤':'<')+' '+qs(c.hi)).join(' or '); }
/* where a formula is named: roots need what is not negative, bottoms need what is not 0 */
function fval(t,x,strict){ const e=1e-9; if(t.t==='n') return qf(t.v); if(t.t==='x') return x; if(t.t==='+') return t.a.reduce((s,u)=>s+fval(u,x,strict),0); if(t.t==='*') return t.a.reduce((s,u)=>s*fval(u,x,strict),1);
  if(t.t==='^'){ const b=fval(t.b,x,strict), ee=qf(t.e); if(!isFinite(b)) return NaN; if(t.e.q===2){ if(b<-e||(strict&&b<e)) return NaN; if(ee<0&&b<e) return NaN; return Math.pow(Math.max(b,0),ee); } if(ee<0&&Math.abs(b)<e) return NaN; return Math.pow(b,ee); }
  return NaN; }
function domCrit(t){ const out=[]; let bad=false; const walk=u=>{ if(bad||!u) return; if(u.t==='+'||u.t==='*') u.a.forEach(walk); else if(u.t==='f'){ bad=true; } else if(u.t==='^'){ walk(u.b); if(qint(u.e)&&u.e.p>=0) return;
      const c=toPoly(u.b); if(c){ const rs=ratRoots(c); if(rs===null) bad=true; else out.push(...rs); return; }
      /* c + k√v */ const b=u.b; if(b.t==='+'&&b.a.length===2){ const cn=b.a.find(w=>w.t==='n'), rt=b.a.find(w=>w!==cn); if(cn){ let k=Q(1), r=rt; if(rt.t==='*'&&rt.a.length===2&&rt.a[0].t==='n'){ k=rt.a[0].v; r=rt.a[1]; }
        if(r.t==='^'&&qe(r.e,Q(1,2))){ const v=toPoly(r.b); if(v){ const w=qd(qn(cn.v),k); if(w.p>=0){ const rs=ratRoots(psub(v,[qm(w,w)])); if(rs===null) bad=true; else out.push(...rs); } return; } } } } bad=true; } };
  walk(t); return bad?null:out; }
const domSet=(t,strict,flip)=>{ const cr=domCrit(t); if(!cr) return null; return realSet(flip?cr.map(qn):cr,x=>isFinite(fval(t,qf(flip?qn(x):x),strict))); };
SEEDS.push({id:'9f.bkformulas',step:'9f',kind:'fn',label:'sums and composites of roots and reciprocals',make(){ const k=rnd(5), r=ri(1,5), a=ri(-5,5), b=ri(-5,5); let t;
  const sq=u=>P(u,Q(1,2)), rx=A(N(r*r),M(N(-1),P(X,2)));
  if(k===0) t=sq(rx); else if(k===1) t=A(sq(rx),sq(A(P(X,2),N(-r*r)))); else if(k===2){ if(a===b||a===-b) return null; t=A(P(lin(1,-a),-1),P(lin(1,-b),-1)); }
  else if(k===3){ if(a===b) return null; t=A(sq(lin(-1,a)),sq(lin(1,-b))); } else { const [R,c]=pick1([[5,4],[5,3],[13,12],[13,5],[10,8],[10,6],[5,5],[5,7]]); t=sq(A(N(c),M(N(-1),sq(A(N(R*R),M(N(-1),P(X,2))))))); }
  return {val:fnv(t),ix:k+':'+r+','+a+','+b,pts:[0,1]}; }});
L.push({id:'9f.natdomain',from:'fn',to:'word',steps:()=>['9f'],say:(p,nm)=>'find the natural domain of '+nm+': every x where it is named',
  act:s=>{ const S=domSet(s.t); if(!S) return null; const w=setText(S); return w==='every real x'||w.length>44?null:word(w); }, cite:()=>'the composite-domain technique',
  slips:s=>{ const S=domSet(s.t); if(!S) return []; const r=setText(S), out=[]; const t2=domSet(s.t,true); if(t2) out.push({why:'the ends are left out, as if a root needed what is above 0',k:'word',s:setText(t2)});
    const f=domSet(s.t,false,true); if(f) out.push({why:'the signs inside the brackets are read at face value',k:'word',s:setText(f)});
    if(s.t.t==='+'){ const g=domSet(s.t.a[0]); if(g) out.push({why:'only the first term is looked at, though a sum is named only where both terms are',k:'word',s:setText(g)}); } return out.filter(w=>w.s!==r); },
  line:(o,p,nm)=>'the natural domain of '+nm+': '+o.s});
/* where a quotient of polynomials is above or below 0 */
const signSet=(t,dir,mode)=>{ const r=rat(t); if(!r) return null; const a=ratRoots(ptrim(r[0])), b=pdeg(r[1])>0?ratRoots(r[1]):[]; if(a===null||b===null||pzero(r[0])) return null;
  const sg0=x=>{ if(mode==='top') return qf(pev(r[0],x))*dir>0; const v=ratEv(r,x); return v!==null&&qf(v)*dir>0; }; return realSet(a.concat(mode==='top'?[]:b),mode==='flip'?(x=>sg0(qn(x))):sg0); };
const fl=S=>S&&{pts:S.pts,reg:S.reg};
SEEDS.push({id:'8g.bkineqs',step:'8g',kind:'fn',label:'the side of an inequality moved over against 0',make(){ const k=rnd(8), r=ri(-5,3), s=r+ri(1,5), a=nz(-5,5), b=nz(-5,5); let t;
  if(k===0) t=lin(nz(-4,4),nz(-9,9)); else if(k===1) t=A(M(N(-1),P(X,2)),N(pick1([1,4,9,16,25,-3,-5]))); else if(k===2){ const B=pick1([-4,-2,2,4]); t=A(P(X,2),M(N(B),X),N(B*B/4+ri(1,4))); }
  else if(k===3) t=simp(M(A(X,N(-r)),A(X,N(-s)))); else if(k===4){ const z=shuffle([-4,-3,-2,-1,0,1,2,3,4]).slice(0,3); t=M(...z.map(c=>c===0?X:A(X,N(-c)))); }
  else if(k===5){ const u=ri(1,4), v=u+ri(1,4); t=A(X,M(N(u*v),P(X,-1)),N(-(u+v))); } else if(k===6){ if(a===b) return null; t=M(lin(1,-a),P(lin(1,-b),-1)); }
  else { const v=a+ri(1,5); t=A(P(lin(1,-a),-1),P(lin(-1,v),-1)); }
  return {val:fnv(t),ix:k+':'+show(t),pts:[0,1]}; }});
L.push({id:'8g.sign',from:'fn',to:'word',steps:()=>['8g'],make:()=>({dir:pick1([1,-1])}),say:(p,nm)=>'find every x where '+nm+'(x) is '+(p.dir>0?'above':'below')+' 0',
  act:(s,p)=>{ const S=signSet(s.t,p.dir); if(!S) return null; const w=setText(S); return w.length>44?null:word(w); }, cite:()=>'the sign chart',
  slips:(s,p)=>{ const S=signSet(s.t,p.dir); if(!S) return []; const r=setText(S), out=[]; const o=signSet(s.t,-p.dir); if(o) out.push({why:'the order is turned: the other sign is read',k:'word',s:setText(o)});
    const f=signSet(s.t,p.dir,'flip'); if(f) out.push({why:'the zeros are read with the signs inside the brackets at face value',k:'word',s:setText(f)});
    const r0=rat(s.t); if(r0&&pdeg(r0[1])>0){ const tp=signSet(s.t,p.dir,'top'); if(tp) out.push({why:'the bottom is multiplied through as if it were positive',k:'word',s:setText(tp)}); } return out.filter(w=>w.s!==r); },
  line:(o,p,nm)=>nm+'(x) is '+(p.dir>0?'above':'below')+' 0 for: '+o.s});
/* the reals where a polynomial is near 0: |f(x)| < d */
const barSet=(c,d,mode)=>{ const lo=ratRoots(padd(c,[Q(d)])), hi=ratRoots(psub(c,[Q(d)])); if(lo===null||hi===null) return null;
  const test=x=>{ const v=qf(pev(c,x)); return mode==='upper'?v<d:mode==='le'?Math.abs(v)<=d:mode==='pos'?(Math.abs(v)<d&&qf(x)>=0):Math.abs(v)<d; }; return realSet(lo.concat(hi),test); };
