ML({id:'27d.newbasis',to:'mat',steps:()=>['27d','27b'],make:()=>{ const P=unimod(2); return P.flat().some(x=>Math.abs(x)>4)?null:{_p:P}; },say:(p,nm)=>'write the map of '+nm+' in the basis '+'('+p._p[0][0]+', '+p._p[1][0]+'), ('+p._p[0][1]+', '+p._p[1][1]+')'.replace(/-/g,'−'),
  act:(s,p)=>{ const P=mm(p._p), Pi=ginv(P); return Pi?mat(gmul(Pi,gmul(s.m,P))):null; },cite:()=>'the columns technique',
  slips:(s,p)=>{ const P=mm(p._p), Pi=ginv(P); if(!Pi) return []; const R=gmul(Pi,gmul(s.m,P)); return [{why:'the basis change is done the wrong way round, P before and its undo after',k:'mat',m:gmul(P,gmul(s.m,Pi))},{why:'the undo of P is left off',k:'mat',m:gmul(s.m,P)}].filter(w=>!geq(w.m,R)); },
  line:(o,p,nm)=>nm+' in the new basis: '+KIND.mat.show(o)});
ML({id:'27k.detplusI',to:'num',steps:()=>['27k'],say:(p,nm)=>'take the determinant of I + '+nm,act:s=>num(det2(gadd(gI(2),s.m))),cite:()=>'the expansion technique',
  slips:s=>[{why:'the determinant is taken to add: det I + det A',v:qa(Q(1),det2(s.m))},{why:'the 1 from I is left out',v:qa(tr2(s.m),det2(s.m))}],line:(o,p,nm,nx,s)=>'det(I + '+nm+') from the trace: 1 + '+par(tr2(s.m))+' + '+par(det2(s.m))+' = '+qs(o.v)});
ML({id:'27g.adjugate',to:'mat',steps:()=>['27g'],say:(p,nm)=>'write the stand-in grid S of '+nm+', with S'+nm+' = (det '+nm+')I',act:s=>mat([[s.m[1][1],qn(s.m[0][1])],[qn(s.m[1][0]),s.m[0][0]]]),cite:()=>'the stand-in technique',
  slips:s=>[{why:'the corners are swapped but the other two keep their signs',k:'mat',m:[[s.m[1][1],s.m[0][1]],[s.m[1][0],s.m[0][0]]]},{why:'the other two are swapped as well as having their signs turned',k:'mat',m:[[s.m[1][1],qn(s.m[1][0])],[qn(s.m[0][1]),s.m[0][0]]]}].filter(w=>!geq(w.m,[[s.m[1][1],qn(s.m[0][1])],[qn(s.m[1][0]),s.m[0][0]]])),
  line:(o,p,nm)=>'the stand-in grid of '+nm+': '+KIND.mat.show(o)});
const least2=m=>{ const c=minPoly(m); return c?facTree(c):null; };
ML({id:'27g.least2',to:'fn',steps:()=>['27g'],say:(p,nm)=>'find the least polynomial of '+nm+', with top coefficient 1',act:s=>{ const t=least2(s.m); return t&&fshort(t)?fnv(t):null; },cite:()=>'the least-obeyed technique',
  slips:s=>{ const t=least2(s.m); if(!t) return []; const own=facTree(ownPoly(s.m)), R=show(t); return [{why:'the own polynomial is given, though a smaller one is obeyed',t:own},{why:'the middle sum is taken with its sign kept',t:fromPoly([det2(s.m),tr2(s.m),Q(1)])}].filter(w=>show(w.t)!==R); },
  line:(o,p,nm)=>'the least polynomial of '+nm+': '+show(o.t)});
ML({id:'27b.readings',to:'vec',steps:()=>['27b','27d'],make:()=>({c:[nz(-3,3),nz(-3,3)]}),say:(p,nm,cur)=>{ if(!cur||!cur.m) return ''; const w=gmul(cur.m,[[Q(p.c[0])],[Q(p.c[1])]]); return 'read w = ('+qs(w[0][0])+', '+qs(w[1][0])+') in the basis made of the columns of '+nm; },
  act:(s,p)=>qz(det2(s.m))?null:vec([Q(p.c[0]),Q(p.c[1])]),cite:()=>'the undoable-group technique',
  slips:(s,p)=>{ if(qz(det2(s.m))) return []; const w=gmul(s.m,[[Q(p.c[0])],[Q(p.c[1])]]).map(r=>r[0]); return [{why:'the entries of w are given, its readings in the first basis',k:'vec',u:w},{why:'the two readings are given in swapped places',k:'vec',u:[Q(p.c[1]),Q(p.c[0])]},{why:'w is sent through the grid instead of through its undo',k:'vec',u:gmul(s.m,w.map(x=>[x])).map(r=>r[0])}].filter(w2=>!(qe(w2.u[0],Q(p.c[0]))&&qe(w2.u[1],Q(p.c[1])))); },
  line:(o,p,nm,nx,s)=>{ const w=gmul(s.m,[[Q(p.c[0])],[Q(p.c[1])]]); return 'the readings of ('+qs(w[0][0])+', '+qs(w[1][0])+') in the columns of '+nm+': '+KIND.vec.show(o); }});
ML({id:'27h.readfirst',to:'vec',steps:()=>['27h'],say:(p,nm)=>'find (a, b) with ax + by 1 on column 1 of '+nm+' and 0 on column 2',act:s=>{ const v=ginv(s.m); return v?vec(v[0]):null; },cite:()=>'the reading-basis technique',
  slips:s=>{ const v=ginv(s.m); if(!v) return []; return [{why:'the second row of the undo is taken, the reading for column 2',k:'vec',u:v[1]},{why:'the entries of column 1 are used as the coefficients',k:'vec',u:[s.m[0][0],s.m[1][0]]},{why:'the first column of the undo is taken instead of its first row',k:'vec',u:[v[0][0],v[1][0]]}].filter(w=>!(qe(w.u[0],v[0][0])&&qe(w.u[1],v[0][1]))); },
  line:(o,p,nm)=>'the first reading of the columns of '+nm+': '+KIND.vec.show(o)});
ML({id:'27g.pullback',to:'vec',steps:()=>['27g','27h'],make:()=>({f:[nz(-3,3),ri(-3,3)]}),say:(p,nm)=>'give the coefficients of the reading v ↦ f('+nm+'v), with f(x, y) = '+show(simp(A(M(N(p.f[0]),X),N(0)))).replace('x','x')+(p.f[1]?(p.f[1]<0?' − ':' + ')+(Math.abs(p.f[1])===1?'':Math.abs(p.f[1]))+'y':''),
  act:(s,p)=>{ const f=[Q(p.f[0]),Q(p.f[1])]; return vec([qa(qm(s.m[0][0],f[0]),qm(s.m[1][0],f[1])),qa(qm(s.m[0][1],f[0]),qm(s.m[1][1],f[1]))]); },cite:()=>'the turn-round technique',
  slips:(s,p)=>{ const f=[Q(p.f[0]),Q(p.f[1])], R=[qa(qm(s.m[0][0],f[0]),qm(s.m[1][0],f[1])),qa(qm(s.m[0][1],f[0]),qm(s.m[1][1],f[1]))]; return [{why:'the grid acts on the coefficients without being turned on its side',k:'vec',u:[qa(qm(s.m[0][0],f[0]),qm(s.m[0][1],f[1])),qa(qm(s.m[1][0],f[0]),qm(s.m[1][1],f[1]))]},{why:'the map is left out and f kept as it was',k:'vec',u:f}].filter(w=>!(qe(w.u[0],R[0])&&qe(w.u[1],R[1]))); },
  line:(o,p,nm)=>'the coefficients of f after '+nm+': '+KIND.vec.show(o)});
const eig2=m=>{ const r=ratRoots(fromPolyC(m)); return r; }; function fromPolyC(m){ return [det2(m),qn(tr2(m)),Q(1)]; }
const kerv=(m,c)=>{ const B=gadd(m,gI(2),qn(c)); let v=!qz(B[0][1])||!qz(B[0][0])?[qn(B[0][1]),B[0][0]]:[qn(B[1][1]),B[1][0]]; if(v.every(qz)) return null; const L2=lcmd(v); v=v.map(x=>qm(x,Q(L2))); const g=Math.abs(gcd(v[0].p,v[1].p))||1; v=v.map(x=>Q(x.p/g)); if(v[0].p<0||(qz(v[0])&&v[1].p<0)) v=v.map(qn); return v; };
ML({id:'27f.stretched',to:'vec',steps:()=>['27f'],make:cur=>{ if(!cur||!cur.m) return null; const r=eig2(cur.m); if(!r||r.length!==2) return null; return {c:pick1(r)}; },say:(p,nm)=>'find the whole v, no common factor, lead entry positive, with '+nm+'v = '+(p.c.q>1?'('+qs(p.c)+')':qs(p.c))+'v',
  act:(s,p)=>{ const r=eig2(s.m); if(!r||!r.some(x=>qe(x,p.c))) return null; const v=kerv(s.m,p.c); return v?vec(v):null; },cite:()=>'the stretch-test technique',
  slips:(s,p)=>{ const r=eig2(s.m)||[], o=r.find(x=>!qe(x,p.c)), v=kerv(s.m,p.c); if(!v) return []; const out=[]; if(o){ const w=kerv(s.m,o); if(w) out.push({why:'the list stretched by the other stretch, '+qs(o)+', is given',k:'vec',u:w}); } out.push({why:'the entries of the list are given in swapped places',k:'vec',u:[v[1],v[0]]}); return out.filter(w=>!(qe(w.u[0],v[0])&&qe(w.u[1],v[1]))); },
  line:(o,p,nm)=>'the list that '+nm+' stretches by '+qs(p.c)+': '+KIND.vec.show(o)});
const STR=['yes: two different real stretches','yes: it is already c times I','no: one repeated stretch, not c times I','no: it has no real stretch'];
const strW=(m,sw)=>{ const t=tr2(m), d=det2(m), disc=qsub(qm(t,t),qm(Q(4),d)), s=sw?-sgn(disc):sgn(disc); if(s>0) return STR[0]; if(s<0) return STR[3]; return qz(m[0][1])&&qz(m[1][0])&&qe(m[0][0],m[1][1])?STR[1]:STR[2]; };
ML({id:'27f.straightens',to:'word',steps:()=>['27f'],say:(p,nm)=>'say whether '+nm+' is diagonal in some real basis, and why',act:s=>word(strW(s.m)),cite:()=>'the straighten-out technique',
  slips:s=>{ const R=strW(s.m); return [{why:'the test (middle sum)² − 4 det is read with its sign turned',k:'word',s:strW(s.m,true)},{why:'a repeated stretch is taken as enough',k:'word',s:R===STR[2]?STR[0]:R},{why:'a grid with one repeated stretch is taken to be c times I',k:'word',s:R===STR[2]?STR[1]:R}].filter(w=>w.s!==R); },
  line:(o,p,nm)=>nm+' in a real basis: '+o.s});
ML({id:'44·cb27.killer',to:'fn',steps:()=>['44·cb27'],make:()=>({v:[nz(-2,2),ri(-2,2)]}),say:(p,nm)=>'find p of least degree, top coefficient 1, with p('+nm+')v = 0, v = ('+p.v.join(', ').replace(/-/g,'−')+')',
  act:(s,p)=>{ const v=p.v.map(x=>Q(x)), Av=[qa(qm(s.m[0][0],v[0]),qm(s.m[0][1],v[1])),qa(qm(s.m[1][0],v[0]),qm(s.m[1][1],v[1]))], dt=qsub(qm(v[0],Av[1]),qm(v[1],Av[0]));
    if(qz(dt)){ const c=!qz(v[0])?qd(Av[0],v[0]):qd(Av[1],v[1]); return fnv(qz(c)?X:A(X,N(qn(c)))); } const t=facTree(fromPolyC(s.m)); return fshort(t)?fnv(t):null; },cite:()=>'the grid-module technique',
  slips:(s,p)=>{ const own=facTree(fromPolyC(s.m)), r=eig2(s.m)||[]; return [{why:'the own polynomial of the grid is given, whatever v is',t:own}].concat(r.map(c=>({why:'v is taken to be only stretched, by '+qs(c),t:qz(c)?X:A(X,N(qn(c)))}))); },
  line:(o,p,nm)=>'the least killer of ('+p.v.join(', ').replace(/-/g,'−')+') under '+nm+': '+show(o.t)});
ML({id:'44·cb27.maker',to:'word',steps:()=>['44·cb27'],make:()=>({v:[nz(-2,2),ri(-2,2)]}),say:(p,nm)=>'for v = ('+p.v.join(', ').replace(/-/g,'−')+'), say whether v and '+nm+'v build the whole plane',
  act:(s,p)=>{ const v=p.v.map(x=>Q(x)), Av=[qa(qm(s.m[0][0],v[0]),qm(s.m[0][1],v[1])),qa(qm(s.m[1][0],v[0]),qm(s.m[1][1],v[1]))]; return word(qz(qsub(qm(v[0],Av[1]),qm(v[1],Av[0])))?'no: v is only stretched, and makes a line':'yes: v and '+'its image are a basis'); },cite:()=>'the companion technique',
  slips:(s,p)=>{ const R=null; return [{why:'a grid with two different stretches is taken to make the plane from any v',k:'word',s:'yes: v and its image are a basis'},{why:'v is taken as only stretched because the grid has a whole stretch',k:'word',s:'no: v is only stretched, and makes a line'}]; },
  line:(o,p,nm)=>'v = ('+p.v.join(', ').replace(/-/g,'−')+') and '+nm+'v: '+o.s.replace('its image',nm+'v')});
ML({id:'44·cb27.parts',to:'mat',steps:()=>['44·cb27'],say:(p,nm)=>'write D in '+nm+' = D + N, D diagonal in some basis, Nᵏ = 0, DN = ND',
  act:s=>{ const r=eig2(s.m); if(!r||!r.length) return null; if(r.length===2) return mat(s.m); const c=r[0]; return mat([[c,Q(0)],[Q(0),c]]); },cite:()=>'the near-diagonal technique',
  slips:s=>{ const r=eig2(s.m); if(!r||!r.length) return []; const R=r.length===2?s.m:[[r[0],Q(0)],[Q(0),r[0]]]; return [{why:'the middle of the grid is taken for D',k:'mat',m:[[s.m[0][0],Q(0)],[Q(0),s.m[1][1]]]},{why:'D is taken to be the grid itself',k:'mat',m:s.m}].filter(w=>!geq(w.m,R)); },
  line:(o,p,nm)=>'the diagonal part D of '+nm+': '+KIND.mat.show(o)});
ML({id:'44·cb27.root',to:'mat',steps:()=>['44·cb27'],say:(p,nm)=>'find the grid B, its stretch positive, with B² = '+nm,
  act:s=>{ const r=eig2(s.m); if(!r||r.length!==1||r[0].p<=0) return null; const c=qsqrt(r[0]); if(!c) return null; const Nn=gadd(s.m,gI(2),qn(r[0])); if(!geq(gmul(Nn,Nn),[[Q(0),Q(0)],[Q(0),Q(0)]])) return null; return mat(gadd(gsc(gI(2),c),Nn,qi(qm(Q(2),c)))); },cite:()=>'the near-diagonal technique',
  slips:s=>{ const r=eig2(s.m); if(!r||r.length!==1||r[0].p<=0) return []; const c=qsqrt(r[0]); if(!c) return []; const Nn=gadd(s.m,gI(2),qn(r[0])); return [{why:'the 2 in N/(2c) is dropped',k:'mat',m:gadd(gsc(gI(2),c),Nn,qi(c))},{why:'the root is taken of the middle only, and the rest kept',k:'mat',m:gadd(gsc(gI(2),c),Nn)}]; },
  line:(o,p,nm)=>'the root of '+nm+': '+KIND.mat.show(o)});
const pd2=m=>!qe(m[0][1],m[1][0])?null:m[0][0].p<=0?'not positive definite: corner 1 is '+qs(m[0][0]):det2(m).p<=0?'not positive definite: corner 2 is '+qs(det2(m)):'positive definite';
ML({id:'31e.corners',to:'word',steps:()=>['31e'],say:(p,nm)=>'by its corner determinants, is the form of '+nm+' positive definite?',act:s=>{ const w=pd2(s.m); return w?word(w):null; },cite:()=>'the form-test technique',
  slips:s=>{ const R=pd2(s.m); if(!R) return []; return [{why:'only the middle entries are checked for being positive',k:'word',s:s.m[0][0].p>0&&s.m[1][1].p>0?'positive definite':R},{why:'the last corner, the whole determinant, is skipped',k:'word',s:s.m[0][0].p>0?'positive definite':R}].filter(w=>w.s!==R); },
  line:(o,p,nm)=>'the form of '+nm+': '+o.s});
ML({id:'31d.symprod',to:'word',steps:()=>['31d','27g'],make:()=>{ const a=ri(-3,3), b=nz(-2,2), c=ri(-3,3); return {_b:[[a,b],[b,c]]}; },say:(p,nm)=>'with B = '+KIND.mat.show({m:mm(p._b)})+', say whether '+nm+'B is symmetric',
  act:(s,p)=>{ if(!qe(s.m[0][1],s.m[1][0])) return null; const B=mm(p._b), AB=gmul(s.m,B); return word(qe(AB[0][1],AB[1][0])?'symmetric':'not symmetric'); },cite:()=>'the side-turn technique',
  slips:(s,p)=>{ const B=mm(p._b), AB=gmul(s.m,B), sy=qe(AB[0][1],AB[1][0]); return sy?[{why:'(AB)ᵀ is taken as AᵀBᵀ, the wrong order, and a mismatch is expected',k:'word',s:'not symmetric'}]:[{why:'a product of symmetric grids is taken to be symmetric',k:'word',s:'symmetric'}]; },
  line:(o,p,nm)=>nm+' times '+KIND.mat.show({m:mm(p._b)})+': '+o.s});
const keeps=m=>geq(gmul(gT(m),m),gI(2));
ML({id:'31d.keeps',to:'word',steps:()=>['31d'],say:(p,nm)=>'say whether '+nm+' keeps the dot: ('+nm+'x)·('+nm+'y) = x·y for all x, y',act:s=>word(keeps(s.m)?'it keeps the dot':'it does not keep the dot'),cite:()=>'the product-keeper technique',
  slips:s=>{ const k=keeps(s.m), d=qabs(det2(s.m)); return [{why:'a determinant of size 1 is taken as enough',k:'word',s:qe(d,Q(1))?'it keeps the dot':'it does not keep the dot'},{why:'columns of size 1 are taken as enough, without checking they meet at right angles',k:'word',s:[0,1].every(j=>qe(qa(qm(s.m[0][j],s.m[0][j]),qm(s.m[1][j],s.m[1][j])),Q(1)))?'it keeps the dot':'it does not keep the dot'}].filter(w=>w.s!==(k?'it keeps the dot':'it does not keep the dot')); },
  line:(o,p,nm)=>nm+' and the dot: '+o.s});

/* ================= I. sizes and products (31a, 31g), polynomials (14i, 23b, 27b, 44j, 44·cb27), clocks (5·cb2, 43b), roots (25d, 44f) ================= */
const dot=(u,w)=>qa(qm(u[0],w[0]),qm(u[1],w[1])), vs=w=>'('+w.map(x=>qs(qq(x))).join(', ')+')';
L.push({id:'31a.diffsq',from:'vec',to:'num',steps:()=>['31a'],make:()=>({w:[nz(-3,3),ri(-3,3)]}),say:(p,nm)=>'find ‖'+nm+' − w‖² for w = '+vs(p.w)+', from ‖'+nm+'‖², ⟨'+nm+', w⟩ and ‖w‖²',
  act:(s,p)=>{ const w=p.w.map(x=>Q(x)); return num(qa(qsub(dot(s.u,s.u),qm(Q(2),dot(s.u,w))),dot(w,w))); },cite:()=>'the square-sum technique',
  slips:(s,p)=>{ const w=p.w.map(x=>Q(x)), a=dot(s.u,s.u), b=dot(s.u,w), c=dot(w,w); return [{why:'the middle term is added instead of taken away',v:qa(qa(a,qm(Q(2),b)),c)},{why:'the middle term is left out',v:qa(a,c)},{why:'the middle term is taken once, not twice',v:qa(qsub(a,b),c)}]; },
  line:(o,p,nm,nx,s)=>{ const w=p.w.map(x=>Q(x)); return 'the size ‖'+nm+' − '+vs(p.w)+'‖² = '+qs(dot(s.u,s.u))+' − 2·'+par(dot(s.u,w))+' + '+qs(dot(w,w))+' = '+qs(o.v); }});
L.push({id:'31a.polar',from:'vec',to:'num',steps:()=>['31a'],make:()=>({w:[nz(-3,3),nz(-3,3)]}),say:(p,nm)=>'with w = '+vs(p.w)+', find ⟨'+nm+', w⟩ from ‖'+nm+' + w‖² and ‖'+nm+' − w‖² alone',
  act:(s,p)=>{ const w=p.w.map(x=>Q(x)), S=dot(s.u.map((x,i)=>qa(x,w[i])),s.u.map((x,i)=>qa(x,w[i]))), D=dot(s.u.map((x,i)=>qsub(x,w[i])),s.u.map((x,i)=>qsub(x,w[i]))); return num(qm(qsub(S,D),Q(1,4))); },cite:()=>'the square-sum technique',
  slips:(s,p)=>{ const w=p.w.map(x=>Q(x)), S=dot(s.u.map((x,i)=>qa(x,w[i])),s.u.map((x,i)=>qa(x,w[i]))), D=dot(s.u.map((x,i)=>qsub(x,w[i])),s.u.map((x,i)=>qsub(x,w[i]))); return [{why:'the difference is halved instead of quartered',v:qm(qsub(S,D),Q(1,2))},{why:'the difference is not divided at all',v:qsub(S,D)}]; },
  line:(o,p,nm,nx,s)=>{ const w=p.w.map(x=>Q(x)), S=dot(s.u.map((x,i)=>qa(x,w[i])),s.u.map((x,i)=>qa(x,w[i]))), D=dot(s.u.map((x,i)=>qsub(x,w[i])),s.u.map((x,i)=>qsub(x,w[i]))); return 'the pairing ⟨'+nm+', '+vs(p.w)+'⟩ = ('+qs(S)+' − '+qs(D)+')/4 = '+qs(o.v); }});
NL({id:'31g.matched',steps:()=>['31g'],say:()=>'find the power q matched with p, p the number',act:s=>qlt(Q(1),s.v)?num(qd(s.v,qsub(s.v,Q(1)))):null,cite:()=>'the matched-powers technique',
  slips:s=>qlt(Q(1),s.v)?[{why:'q is taken as p − 1',v:qsub(s.v,Q(1))},{why:'1/p + 1/q = 1 is read as q = 1/p',v:qi(s.v)},{why:'the fraction is turned over: (p − 1)/p',v:qd(qsub(s.v,Q(1)),s.v)}]:[],
  line:(o,p,nm,nx,s)=>'matched with p = '+qs(s.v)+': q = p/(p − 1) = '+qs(o.v)});
/* ratios whose top and bottom both vanish */
SEEDS.push({id:'14i.bkratios',step:'14i',kind:'fn',label:'a ratio of polynomials whose top and bottom share a zero',make(){ const [r,s,u]=shuffle([-3,-2,-1,1,2,3,4]).slice(0,3), k=rnd(2);
  const f=k?pmul(P_([-r,1]),P_([-s,1])):pmul(pmul(P_([-r,1]),P_([-r,1])),P_([-s,1])), g=k?pmul(P_([-r,1]),P_([-u,1])):pmul(P_([-r,1]),P_([-u,1])); return {val:fnv(M(fromPoly(f),P(fromPoly(g),-1))),ix:[r,s,u,k].join(','),pts:[0,1,2]}; }});
const sharedZero=t=>{ const q=quotParts(t); if(!q||t.t!=='*') return null; const zs=ratRoots(q[1]); if(!zs) return null; const c=zs.filter(z=>qz(pev(q[0],z))); return c.length?{q,c}:null; };
const headsTo=(q,a)=>{ let [f,g]=q, k=0; while(qz(pev(f,a))&&qz(pev(g,a))&&k<4){ f=pder(f); g=pder(g); k++; } const b=pev(g,a); return qz(b)?null:qd(pev(f,a),b); };
