  ang:{show:v=>angs(v.t), seed:v=>'θ = '+angs(v.t), ok:v=>!big(v.t)&&v.t.q<=12&&Math.abs(v.t.p)<=48},
  line:{show:v=>ltx(v.a,v.b,v.c), seed:v=>'ℓ: '+ltx(v.a,v.b,v.c), ok:v=>[v.a,v.b,v.c].every(x=>Math.abs(x.p)<=40)},
