    const p={}; if(FIRSTX.has(W.id)||W.px) p.x=pick(S.pts); if(W.area){ const e=S.ends?pick(S.ends):(()=>{ const a=pick([0,0,1]); return [a,a+ri(1,3)]; })(); p.a=e[0]; p.b=e[1]; }
    if(W.id==='9a.read'&&S.early&&Math.random()<0.5) continue;
